(function () {
  'use strict';

  var shareBtn = document.getElementById('share-btn');
  var statusEl = document.getElementById('share-status');

  if (!shareBtn || !statusEl) return;

  var LABELS = {
    share: 'Compartir',
    sharing: 'Compartiendo…',
    copying: 'Copiando…',
    copied: 'Enlazado copiado',
    error: 'No se pudo compartir'
  };

  // Try to integrate with existing translation system if present
  try {
    if (window.App && window.App.i18n) {
      var t = window.App.i18n;
      LABELS.share = t('share') || LABELS.share;
      // ... etc
    }
  } catch (e) {}

  function setStatus(msg) {
    statusEl.textContent = msg || '';
  }

  function shareViaWebApi() {
    var shareData = {
      title: document.title || 'Compartir',
      url: window.location.href
    };

    if (navigator.share && (navigator.canShare ? navigator.canShare(shareData) : true)) {
      return Promise.resolve(navigator.share(shareData));
    }
    return null;
  }

  function shareViaClipboard() {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      return navigator.clipboard.writeText(window.location.href);
    }
    return Promise.reject(new Error('Clipboard not available'));
  }

  shareBtn.addEventListener('click', function () {
    setStatus(LABELS.sharing);
    shareBtn.disabled = true;

    var apiPromise = shareViaWebApi();

    if (apiPromise) {
      apiPromise
        .then(function () {
          setStatus(LABELS.copied);
          resetAfterDelay();
        })
        .catch(function () {
          // Fallback to clipboard
          setStatus(LABELS.copying);
          shareViaClipboard()
            .then(function () {
              setStatus(LABELS.copied);
              resetAfterDelay();
            })
            .catch(function () {
              setStatus(LABELS.error);
              shareBtn.disabled = false;
            });
        });
    } else {
      // No native share available, go straight to clipboard
      setStatus(LABELS.copying);
      shareViaClipboard()
        .then(function () {
          setStatus(LABELS.copied);
          resetAfterDelay();
        })
        .catch(function () {
          setStatus(LABELS.error);
          shareBtn.disabled = false;
        });
    }
  });

  function resetAfterDelay() {
    setTimeout(function () {
      setStatus('');
      shareBtn.disabled = false;
    }, 2500);
  }

  // Revert state on navigation/visibility change
  window.addEventListener('beforeunload', function () { shareBtn.disabled = false; });
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) { shareBtn.disabled = false; setStatus(''); }
  });
})();
```

